<!-- 文件作用：俱乐部详情、成员申请审核、团队订单及负责人资料管理。 -->
<template><AppShell title="俱乐部" back><view v-if="error" class="error-box mb" @click="load">{{ error }} · 重试</view><template v-if="club"><view class="club-profile"><view class="crest">{{ club.name?.slice(0,1) }}</view><text class="club-title">{{ club.name }}</text><view class="club-verified"><Icon :name="club.verified?'shield':'club'" :size="14"/>{{ club.verified?'平台认证俱乐部':club.status==='active'?'开放成员挂靠':'平台审核中' }}</view><text class="muted">{{ club.owner_name }} 主理 · {{ club.member_count || 0 }} 位成员</text><text class="club-description">{{ club.description }}</text><view class="game-tags"><text v-for="gameId in club.game_ids" :key="gameId" class="pill">{{ gameName(gameId) }}</text></view></view><view v-if="!canManage && club.status==='active'" class="join-panel"><button v-if="membership?.status==='active'" class="btn-secondary" @click="membershipAction('leave')">退出俱乐部</button><button v-else-if="membership?.status==='pending'" class="btn-secondary" disabled>挂靠申请审核中</button><button v-else class="btn" :disabled="busy" @click="membershipAction('join')">申请挂靠</button><text class="hint">加入后可在发布服务时选择该俱乐部，认证图标随审核状态更新。</text></view><view class="tabs mb"><button :class="['tab',{active:tab==='members'}]" @click="tab='members'">{{ canManage?'成员管理':'团队成员' }}</button><button v-if="canManage" :class="['tab',{active:tab==='orders'}]" @click="tab='orders';loadOrders()">团队订单</button><button v-if="canManage" :class="['tab',{active:tab==='settings'}]" @click="tab='settings'">俱乐部资料</button></view>
<template v-if="tab==='members'"><EmptyState v-if="!members.length" title="还没有成员" detail="俱乐部通过审核后，打手可以申请挂靠" icon="club"/><view v-for="member in members" :key="member.user_id" class="member panel"><view class="row"><view class="avatar">{{ member.nickname?.slice(0,1) }}</view><view class="member-info"><text>{{ member.nickname }}</text><text class="hint">{{ member.status==='active'?'已加入':member.status==='pending'?'申请中':'已移除' }} · {{ time(member.created_at) }}</text></view></view><view v-if="canManage && member.user_id!==club.owner_id" class="member-actions"><button v-if="member.status==='pending'" class="btn btn-small" :disabled="busy" @click="reviewMember(member,'active')">同意挂靠</button><button v-if="['pending','active'].includes(member.status)" class="btn btn-secondary btn-small" :disabled="busy" @click="reviewMember(member,'rejected')">{{ member.status==='pending'?'拒绝':'移除成员' }}</button></view></view></template>
<template v-if="tab==='orders'"><text class="hint block">可进入团队订单的聊天室，协助双方履约与处理争议。</text><EmptyState v-if="!orders.length" title="暂无团队订单" detail="挂靠服务产生的订单会出现在这里"/><view v-for="order in orders" :key="order.id" class="panel team-order" @click="go('/pages/order/index?id='+order.id)"><view class="row between"><text class="order-title">{{ order.title }}</text><text class="accent">¥{{ money(order.amount_cents) }}</text></view><text class="hint">{{ order.buyer_name }} → {{ order.provider_name || '等待接单' }}</text><view class="row between"><text class="pill">{{ statusLabel(order.status) }}</text><text class="text-btn">进入聊天室</text></view></view></template>
<view v-if="tab==='settings'" class="panel"><view class="field"><text class="field-label">俱乐部名称</text><input v-model="edit.name" class="input" maxlength="30"/></view><view class="field"><text class="field-label">俱乐部介绍</text><textarea v-model="edit.description" class="input" maxlength="500"/></view><text class="field-label">覆盖游戏</text><view class="game-choices"><button v-for="game in state.games" :key="game.id" :class="['tab',{active:edit.game_ids.includes(game.id)}]" @click="toggleGame(game.id)">{{ game.short_name }}</button></view><button class="btn" :disabled="busy" @click="save">保存资料</button></view>
</template></AppShell></template>
<script setup>
/** 文件作用：隔离俱乐部管理权限，执行申请、审批、退出和团队订单查询。 */
import { ref,reactive,computed } from 'vue'
import { onLoad,onShow } from '@dcloudio/uni-app'
import AppShell from '../../components/AppShell.vue'
import Icon from '../../components/Icon.vue'
import EmptyState from '../../components/EmptyState.vue'
import { state,init } from '../../lib/store'
import { api } from '../../lib/api'
import { go,notify,time,money,statusLabel } from '../../lib/format'
const id=ref(''),club=ref(null),members=ref([]),membership=ref(null),orders=ref([]),tab=ref('members'),busy=ref(false),error=ref(''),edit=reactive({name:'',description:'',game_ids:[]})
const canManage=computed(()=>state.user&&(club.value?.owner_id===state.user.id||state.user.role==='admin'))
/** 同步俱乐部资料与当前用户申请状态。 */
async function load(){if(!id.value)return;try{await init();const result=await api('/clubs/'+id.value);club.value=result.club;members.value=result.members||[];membership.value=result.my_membership;Object.assign(edit,{name:result.club.name,description:result.club.description,game_ids:[...(result.club.game_ids||[])]});error.value=''}catch(e){error.value=e.message}}
/** 查询负责人有权访问的团队订单。 */
async function loadOrders(){try{orders.value=await api('/clubs/'+id.value+'/orders')}catch(e){notify(e)}}
/** 获取游戏名称。 */
function gameName(gameId){return state.games.find(item=>item.id===gameId)?.short_name||gameId}
/** 申请挂靠或退出团队，退出前确认影响。 */
function membershipAction(action){if(!state.user)return go('/pages/login/index');uni.showModal({title:action==='join'?'申请挂靠':'退出俱乐部',content:action==='join'?'俱乐部管理员同意后即可展示对应挂靠信息。':'退出后，新服务不能使用该俱乐部认证，历史订单证据仍会保留。',success:async result=>{if(!result.confirm)return;busy.value=true;try{await api('/clubs/'+id.value+'/'+action,'POST',{});await load();notify(action==='join'?'挂靠申请已提交':'已退出俱乐部')}catch(e){notify(e)}finally{busy.value=false}}})}
/** 审核或移除成员，所有操作由服务端核验负责人权限。 */
async function reviewMember(member,status){if(busy.value)return;busy.value=true;try{await api('/clubs/'+id.value+'/members/'+member.user_id,'POST',{status});await load();notify('成员状态已更新')}catch(e){notify(e)}finally{busy.value=false}}
/** 选择俱乐部服务的游戏。 */
function toggleGame(gameId){const index=edit.game_ids.indexOf(gameId);if(index>=0)edit.game_ids.splice(index,1);else edit.game_ids.push(gameId)}
/** 保存有效的俱乐部资料。 */
async function save(){if(busy.value)return;if(!edit.name.trim()||!edit.description.trim()||!edit.game_ids.length)return notify('请完整填写资料并选择游戏');busy.value=true;try{await api('/clubs/'+id.value,'PATCH',edit);await load();notify('资料已保存')}catch(e){notify(e)}finally{busy.value=false}}
onLoad(options=>{id.value=options.id||'';load()});onShow(()=>{if(id.value)load()})
</script>
<style scoped>.club-profile{text-align:center;padding:10px 12px 28px;display:flex;align-items:center;flex-direction:column;gap:10px}.crest{height:72px;width:72px;border:1px solid var(--accent);background:#ffffff05;color:var(--accent);border-radius:22px;font-weight:800;font-size:33px;display:flex;align-items:center;justify-content:center}.club-title{font-size:26px;font-weight:800;margin-top:6px}.club-verified{color:var(--accent);font-size:11px;display:flex;align-items:center;gap:5px}.club-description{font-size:13px;line-height:1.9;color:#a0b1a7;margin-top:8px}.game-tags{display:flex;flex-wrap:wrap;gap:5px}.join-panel{display:flex;flex-direction:column;gap:10px;margin:0 0 24px}.member{display:flex;flex-direction:column;gap:14px;margin-bottom:12px}.member-info{display:flex;flex-direction:column;gap:4px;font-size:14px}.member-actions{display:flex;gap:9px;justify-content:flex-end}.team-order{display:flex;flex-direction:column;gap:13px;margin-bottom:12px}.order-title{font-weight:650;font-size:14px;max-width:72%}.block{display:block;margin:10px 0 15px}.game-choices{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0 22px}</style>
